// Define the expected response schema
const authSchema = {
    type: "object",
    required: ["token"],
    properties: {
        token: {
            type: "string",
            minLength: 1
        }
    }
};

// Validate JSON schema
pm.test("Authentication response matches JSON schema", function () {
    pm.response.to.have.jsonSchema(authSchema);
});

// Validate token and save it
pm.test("Response contains a valid token", function () {
    pm.expect(response.token).to.be.a("string");
    pm.expect(response.token).to.not.be.empty;
});

if (
    pm.response.code === 200 &&
    typeof response.token === "string" &&
    response.token.length > 0
) {
    pm.environment.set("token", response.token);
    console.log("Authentication successful. Token saved to environment.");
} else {
    console.error("Authentication failed. Token was not updated.");
}

